CREATE OR REPLACE FUNCTION public.cleaning_team_valid(_team uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT active AND public.sched_pro_active(lead_pro_id) AND 'cleaning'::public.service_type=ANY(public.sched_pro_services(lead_pro_id)) AND NOT EXISTS(SELECT 1 FROM public.applicants WHERE contractor_id=lead_pro_id AND coalesce(is_test_row,false)) AND CASE WHEN kind='paired_pros' THEN public.sched_pro_active(partner_pro_id) AND 'cleaning'::public.service_type=ANY(public.sched_pro_services(partner_pro_id)) AND NOT EXISTS(SELECT 1 FROM public.applicants WHERE contractor_id=partner_pro_id AND coalesce(is_test_row,false)) ELSE helper_background_checked_at IS NOT NULL AND helper_insurance_verified_at IS NOT NULL END FROM public.cleaning_teams WHERE id=_team),false) $$;
ALTER POLICY cleaning_team_read ON public.cleaning_teams USING(public.current_user_admin());
CREATE OR REPLACE FUNCTION public.pro_cleaning_visit_details(_visit uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; t public.cleaning_teams; BEGIN SELECT * INTO v FROM public.visits WHERE id=_visit; IF NOT FOUND THEN RAISE EXCEPTION 'visit_not_found'; END IF; SELECT * INTO t FROM public.cleaning_teams WHERE id=v.cleaning_team_id; IF v.assigned_pro_id IS DISTINCT FROM auth.uid() AND t.partner_pro_id IS DISTINCT FROM auth.uid() AND NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN jsonb_build_object('size',v.size_tier,'is_lead',v.assigned_pro_id=auth.uid(),'team',CASE WHEN t.id IS NOT NULL THEN jsonb_build_object('lead',public.sched_pro_first_name(t.lead_pro_id),'partner',CASE WHEN t.kind='paired_pros' THEN public.sched_pro_first_name(t.partner_pro_id) ELSE t.helper_name END) END,'zones',v.cleaning_zones,'inspected',v.cleaning_final_inspection_at IS NOT NULL); END $$;
REVOKE ALL ON FUNCTION public.pro_cleaning_visit_details(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pro_cleaning_visit_details(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.mark_visit_paid_in_full(_visit_id uuid,_reason text,_note text DEFAULT NULL,_actor text DEFAULT 'admin') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.visits; v_pay integer; v_week uuid;
BEGIN
 IF NOT public.is_privileged_caller() THEN RAISE EXCEPTION 'not authorized'; END IF;
 IF _reason IS NULL OR _reason='' THEN RAISE EXCEPTION 'reason_required'; END IF;
 SELECT * INTO v FROM public.visits WHERE id=_visit_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'visit_not_found'; END IF;
 IF v.status::text NOT IN ('scheduled','on_the_way','in_progress') THEN RAISE EXCEPTION 'visit_not_open'; END IF;
 IF v.assigned_pro_id IS NULL THEN RAISE EXCEPTION 'no_pro_assigned'; END IF;
 v_pay:=coalesce(public.pro_tier_uplift_cents(v.contractor_pay_cents,v.assigned_pro_id),v.visit_pay_cents,0);
 UPDATE public.visits SET status='blocked',paid_in_full_reason=_reason,lifecycle_reason=CASE WHEN v.service::text='cleaning' THEN 'partial_pay' ELSE 'paid_in_full' END,visit_pay_cents=v_pay,notes=concat_ws(E'\n',notes,format('[reported · %s · %s] %s',_actor,_reason,coalesce(_note,''))) WHERE id=_visit_id RETURNING visit_pay_cents INTO v_pay;
 IF v.service::text='cleaning' THEN PERFORM public.cleaning_record_pay(v.id); ELSE v_week:=public.credit_payout_week(v.assigned_pro_id,coalesce(v.scheduled_start,now()),v_pay); END IF;
 INSERT INTO public.admin_alerts(alert_type,title,body,context) VALUES('visit_paid_in_full',CASE WHEN v.service::text='cleaning' THEN 'Cleaning visit — half-rate payment' ELSE 'Visit paid in full' END,format('Visit %s paid $%s. Reported by %s. %s',_visit_id,v_pay/100.0,_actor,coalesce(_note,'')),jsonb_build_object('visit_id',_visit_id,'reason',_reason,'pay_cents',v_pay,'actor',_actor));
 RETURN jsonb_build_object('ok',true,'visit_id',_visit_id,'status','blocked','paid_in_full_reason',_reason,'visit_pay_cents',v_pay,'payout_week_id',v_week);
END $$;